-- Stamp every session with the rule version it ran under.
--
-- rules_hash is a sha256 over the user-level CLAUDE.md, its @imports,
-- rules/**/*.md and the active output style, in a fixed order (see
-- src/lib/rules-hash.ts). With ork_version, now resolved from the plugin
-- manifest, it answers "which sessions, branches and worktrees ran under a
-- bad rule" after a rollback (read with bin/sessions-under.mjs).
--
-- Fail loud: the registrar writes the token 'rules_hash_empty' (and
-- 'ork_version_unresolved') instead of NULL when there is nothing to hash or
-- no manifest resolves. NULL therefore means only "row written before 006".

PRAGMA user_version = 6;

ALTER TABLE sessions ADD COLUMN rules_hash TEXT;

CREATE INDEX IF NOT EXISTS idx_sessions_rules_hash ON sessions(rules_hash);
